// Log → record
// ---------------------------------------------------------------------------

#[derive(Clone, Debug)]
struct Dest {
    host: String,
    port: u16,
    outcome: &'static str,
    connections: u64,
    bytes_out: u64,
    bytes_in: u64,
    ips: BTreeSet<String>,
    first_at: String,
    last_at: String,
}

fn outcome_str(s: &str) -> Option<&'static str> {
    OUTCOMES.iter().copied().find(|o| *o == s)
}

fn merge_outcome(a: &'static str, b: &'static str) -> &'static str {
    if a == "blocked" || b == "blocked" {
        "blocked"
    } else if a == "allowed" || b == "allowed" {
        "allowed"
    } else {
        "failed"
    }
}

